package ru.kstolu.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi")
public class PantryUpgradeTest {
 private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity host;private SharedPreferences prefs;private final List<JSONObject> sent=Collections.synchronizedList(new ArrayList<>());
 @Before public void setup()throws Exception{RuntimeEnvironment.getApplication().getSharedPreferences("settings",0).edit().clear().commit();ApiClient.configureForTests(url->{throw new AssertionError("Unexpected network");});controller=Robolectric.buildActivity(MainActivity.class).setup();host=controller.get();prefs=host.getSharedPreferences("settings",0);}
 @After public void close(){controller.pause().stop().destroy();ApiClient.restoreTransport();}
 private void call(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(host);}
 private TextView find(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView x=find(((ViewGroup)v).getChildAt(i),s);if(x!=null)return x;}return null;}
 private View root(){return host.getWindow().getDecorView();}
 private String inventory(){return "{\"kind\":\"inventory\",\"status\":\"ok\",\"products\":[\"Томаты\",\"Рис\"],\"region\":\"Россия\",\"currency\":\"RUB\",\"receiptPrices\":[]}";}
 private void review()throws Exception{prefs.edit().putString("reviewedInventory",inventory()).commit();call("reviewProducts");}
 private HttpURLConnection response(URL url,String text){return new HttpURLConnection(url){final ByteArrayOutputStream body=new ByteArrayOutputStream();public void disconnect(){}public void connect(){}public boolean usingProxy(){return false;}public OutputStream getOutputStream(){return body;}public int getResponseCode()throws IOException{if(body.size()>0)try{sent.add(new JSONObject(body.toString("UTF-8")));}catch(Exception e){throw new IOException(e);}return 200;}public InputStream getInputStream(){return new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));}};}
 private boolean busy(){try{Field f=MainActivity.class.getDeclaredField("busy");f.setAccessible(true);return f.getBoolean(host);}catch(Exception e){throw new AssertionError(e);}}
 private void await()throws Exception{for(int i=0;i<400&&busy();i++){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertFalse(busy());}
 @Test public void mergePreservesReviewedMetadataAndDeduplicates()throws Exception{JSONObject old=new JSONObject(inventory());old.put("products",new JSONArray().put("Свёкла").put("Рис"));JSONObject next=PantryMerge.add(old,new JSONObject().put("products",new JSONArray().put("свекла").put(" Вино ")));assertEquals("[\"Свёкла\",\"Рис\",\"Вино\"]",next.getJSONArray("products").toString());assertEquals("Россия",next.getString("region"));assertEquals(2,old.getJSONArray("products").length());assertEquals("[]",next.getJSONArray("receiptPrices").toString());}
 @Test public void mergeOverflowNeverTruncatesOrMutatesOldList()throws Exception{JSONObject old=new JSONObject(inventory());JSONArray products=new JSONArray();for(int i=0;i<80;i++)products.put("Продукт "+i);old.put("products",products);try{PantryMerge.add(old,new JSONObject().put("products",new JSONArray().put("Новый")));fail();}catch(IllegalArgumentException expected){}assertEquals(80,old.getJSONArray("products").length());}
 @Test public void reviewHasCompactAddActionsAndPersistentLowCaloriePreference()throws Exception{review();assertNotNull(find(root(),"Добавить текстом"));assertNotNull(find(root(),"Добавить по фото"));TextView low=find(root(),"Мало калорий");assertNotNull(low);low.performClick();assertTrue(prefs.getStringSet("preferences",Collections.emptySet()).contains("low_cal"));call("reviewProducts");assertNotNull(find(root(),"✓  Мало калорий"));}
 @Test public void extraRecognitionSendsOnlyNewPhotoAndMergesNames()throws Exception{review();ApiClient.configureForTests(url->response(url,"{\"status\":\"done\",\"result\":{\"kind\":\"inventory\",\"status\":\"ok\",\"products\":[\"рис\",\"Вино\"],\"receiptPrices\":[]}}"));ArrayList<byte[]> photos=new ArrayList<>();photos.add(new byte[]{1,2,3});Method m=MainActivity.class.getDeclaredMethod("recognizeExtraPhotos",ArrayList.class);m.setAccessible(true);m.invoke(host,photos);await();assertEquals(1,sent.size());JSONObject request=sent.get(0);assertEquals("recognize",request.getString("mode"));assertEquals(1,request.getJSONArray("images").length());assertEquals("data:image/jpeg;base64,AQID",request.getJSONArray("images").getString(0));assertFalse(request.has("receipt"));assertEquals("[\"Томаты\",\"Рис\",\"Вино\"]",new JSONObject(prefs.getString("reviewedInventory","{}")).getJSONArray("products").toString());assertFalse(prefs.contains("inventoryAppend"));}
 @Test public void restoredExtraInventoryMergesWithoutSendingPlan()throws Exception{review();prefs.edit().putBoolean("inventoryAppend",true).putString(SelectionClient.READY,"{\"kind\":\"inventory\",\"status\":\"ok\",\"products\":[\"Сыр\"]}").commit();find(root(),"Всё верно — составить блюда").performClick();await();assertEquals(0,sent.size());assertEquals(3,new JSONObject(prefs.getString("reviewedInventory","{}")).getJSONArray("products").length());assertNotNull(find(root(),"Сыр"));}
 @Test public void failedExtraScanKeepsOriginalProducts()throws Exception{review();prefs.edit().putBoolean("inventoryAppend",true).putString(SelectionClient.READY,"{\"kind\":\"inventory\",\"status\":\"bad_photo\",\"message\":\"Снимок нечёткий\"}").commit();find(root(),"Всё верно — составить блюда").performClick();await();assertEquals(2,new JSONObject(prefs.getString("reviewedInventory","{}")).getJSONArray("products").length());assertFalse(prefs.contains("inventoryAppend"));assertFalse(prefs.contains(SelectionClient.READY));}
 @Test public void globalGenerationSwitchRemoved()throws Exception{call("settings");assertNull(find(root(),"Разрешить генерацию фото"));}
 @Test public void imageGenerationNeedsOnlyPerImageConfirmationNotGlobalSwitch()throws Exception{prefs.edit().putBoolean("generation",false).commit();JSONObject recipe=new JSONObject("{\"status\":\"ok\",\"title\":\"Новое блюдо для фото\",\"servings\":2,\"image_prompt\":\"Warm tomatoes and cooked rice together in a plain white bowl, no garnish.\",\"ingredients\":[{\"name\":\"Томаты\",\"amount\":200,\"unit\":\"g\"}],\"steps\":[{\"title\":\"Готовьте\",\"body\":\"Прогрейте томаты.\"}]}");Field selected=MainActivity.class.getDeclaredField("selected");selected.setAccessible(true);selected.set(host,new JSONObject().put("recipe",recipe).put("currency","RUB"));call("requestPhoto");AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(d);assertEquals("Создать одно фото блюда?",org.robolectric.Shadows.shadowOf(d).getTitle().toString());assertEquals(0,sent.size());d.dismiss();}
 @Test @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE) public void reviewVisualLayout()throws Exception{review();View root=root();root.measure(View.MeasureSpec.makeMeasureSpec(390,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(844,View.MeasureSpec.EXACTLY));root.layout(0,0,390,844);Shadows.shadowOf(Looper.getMainLooper()).idle();android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(390,844,android.graphics.Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(image));File out=new File("build/visual-qa-1.3.0");out.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(out,"review.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}image.recycle();}

}
